package com.hermes.jarvis;
import android.os.Bundle;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.hermes.jarvis.core.GitHubManager;import com.hermes.jarvis.utils.PrefsManager;
public class GitHubActivity extends AppCompatActivity{private PrefsManager p;private EditText token,repo,branch;private TextView out;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_github);p=new PrefsManager(this);token=findViewById(R.id.etGhToken);repo=findViewById(R.id.etGhRepo);branch=findViewById(R.id.etGhBranch);out=findViewById(R.id.tvGhOut);token.setText(p.githubToken());repo.setText(p.githubRepo());branch.setText(p.githubBranch());findViewById(R.id.btnGhList).setOnClickListener(v->{p.githubToken(token.getText().toString());p.githubRepo(repo.getText().toString());p.githubBranch(branch.getText().toString());out.setText("Loading…");new GitHubManager().listRepo(token.getText().toString().trim(),repo.getText().toString().trim(),branch.getText().toString().trim(),new GitHubManager.Callback(){public void ok(String t){runOnUiThread(()->out.setText(t));}public void err(String e){runOnUiThread(()->out.setText("❌ "+e));}});});}}
